<?php
require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','accountant']);$bid=current_branch_id();$retentionDays=rule_int('retention_days',14);$riskThreshold=rule_int('retention_visit_threshold',1);$trafficDays=rule_int('traffic_analysis_days',60);
$months=[];for($i=5;$i>=0;$i--){$ts=strtotime("-$i month");$months[date('Y-m',$ts)]=['label'=>date('M',$ts),'revenue'=>0,'expense'=>0,'joins'=>0];}
foreach(query_all("SELECT DATE_FORMAT(payment_date,'%Y-%m') k,SUM(amount) v FROM payments WHERE branch_id=? AND status='paid' AND payment_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY k",[$bid]) as $r) if(isset($months[$r['k']]))$months[$r['k']]['revenue']=(float)$r['v'];
foreach(query_all("SELECT DATE_FORMAT(expense_date,'%Y-%m') k,SUM(amount) v FROM expenses WHERE branch_id=? AND expense_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY k",[$bid]) as $r) if(isset($months[$r['k']]))$months[$r['k']]['expense']=(float)$r['v'];
foreach(query_all("SELECT DATE_FORMAT(join_date,'%Y-%m') k,COUNT(*) v FROM members WHERE branch_id=? AND join_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY k",[$bid]) as $r) if(isset($months[$r['k']]))$months[$r['k']]['joins']=(int)$r['v'];
$plans=query_all("SELECT COALESCE(p.name,'Unknown') label,COUNT(*) value FROM members m LEFT JOIN membership_plans p ON p.id=m.membership_plan_id WHERE m.branch_id=? GROUP BY p.name ORDER BY value DESC",[$bid]);
$traffic=query_all("SELECT HOUR(check_in) h,COUNT(*) value FROM attendance WHERE branch_id=? AND check_in>=DATE_SUB(NOW(),INTERVAL $trafficDays DAY) GROUP BY HOUR(check_in) ORDER BY h",[$bid]);
$trainerPerf=query_all("SELECT t.name,COUNT(DISTINCT m.id) clients,COUNT(DISTINCT w.id) plans,COUNT(DISTINCT a.id) visits FROM trainers t LEFT JOIN members m ON m.trainer_id=t.id AND m.status='active' LEFT JOIN workout_plans w ON w.trainer_id=t.id AND w.status='active' LEFT JOIN attendance a ON a.member_id=m.id AND a.check_in>=DATE_SUB(NOW(),INTERVAL 30 DAY) WHERE t.branch_id=? GROUP BY t.id ORDER BY clients DESC",[$bid]);
$active=(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND status='active' AND membership_end>=CURDATE()",[$bid]);$atRisk=(int)query_value("SELECT COUNT(*) FROM (SELECT m.id,COUNT(a.id) v FROM members m LEFT JOIN attendance a ON a.member_id=m.id AND a.check_in>=DATE_SUB(NOW(),INTERVAL $retentionDays DAY) WHERE m.branch_id=? AND m.status='active' AND m.membership_end>=CURDATE() GROUP BY m.id HAVING v<=$riskThreshold) x",[$bid]);$retention=$active?round((1-$atRisk/$active)*100,1):100;
$revThis=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE branch_id=? AND status='paid' AND payment_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]);$expThis=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE branch_id=? AND expense_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]);
$pageTitle='Business Analytics';include __DIR__.'/../includes/header.php'; ?>
<div class="metric-strip"><div class="metric-box"><small>Retention health*</small><strong><?= $retention ?>%</strong></div><div class="metric-box"><small>Members at risk</small><strong><?= $atRisk ?></strong></div><div class="metric-box"><small>Month net position</small><strong><?= money($revThis-$expThis) ?></strong></div><div class="metric-box"><small>Active base</small><strong><?= $active ?></strong></div></div><p class="text-muted" style="font-size:.65rem">*Demo heuristic: active members with more than one visit in the last <?= $retentionDays ?> days are treated as healthy for the retention watch.</p>
<div class="grid-2"><div class="panel"><div class="panel-head"><div><h3>Revenue vs expenses</h3><p>Six-month operating view</p></div></div><div class="chart-wrap"><canvas id="financeChart"></canvas></div></div><div class="panel"><div class="panel-head"><div><h3>Membership mix</h3><p>Current members by plan</p></div></div><div class="chart-wrap"><canvas id="planChart"></canvas></div></div></div>
<div class="grid-2"><div class="panel"><div class="panel-head"><div><h3>Traffic by hour</h3><p>Last <?= $trafficDays ?> days of check-ins</p></div></div><div class="chart-wrap"><canvas id="trafficChart"></canvas></div></div><div class="panel"><div class="panel-head"><div><h3>New member acquisition</h3><p>Joined members by month</p></div></div><div class="chart-wrap"><canvas id="joinChart"></canvas></div></div></div>
<div class="table-card mt-3"><div class="table-toolbar"><div><strong>Trainer operational view</strong><div class="text-muted" style="font-size:.68rem">Client load and member activity, not a quality score</div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Trainer</th><th>Active clients</th><th>Active plans</th><th>Client visits / 30D</th></tr></thead><tbody><?php foreach($trainerPerf as $t): ?><tr><td><strong><?= e($t['name']) ?></strong></td><td><?= (int)$t['clients'] ?></td><td><?= (int)$t['plans'] ?></td><td><?= (int)$t['visits'] ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php $currencyJs=json_encode((string)setting('currency_symbol','৳'));$labels=array_column($months,'label');$rev=array_column($months,'revenue');$exp=array_column($months,'expense');$joins=array_column($months,'joins');$planLabels=array_column($plans,'label');$planData=array_map('intval',array_column($plans,'value'));$hours=array_map(fn($r)=>date('g A',strtotime($r['h'].':00')), $traffic);$trafficData=array_map(fn($r)=>(int)$r['value'],$traffic);$pageScript='<script>const tick="#7c8793",grid="rgba(255,255,255,.05)",currency='.$currencyJs.';new Chart(financeChart,{type:"bar",data:{labels:'.json_encode($labels).',datasets:[{label:"Revenue",data:'.json_encode($rev).',backgroundColor:"rgba(183,255,74,.75)",borderRadius:7},{label:"Expenses",data:'.json_encode($exp).',backgroundColor:"rgba(255,95,109,.65)",borderRadius:7}]},options:{maintainAspectRatio:false,plugins:{legend:{labels:{color:tick}}},scales:{x:{ticks:{color:tick},grid:{display:false}},y:{ticks:{color:tick,callback:v=>currency+v/1000+"k"},grid:{color:grid}}}}});new Chart(planChart,{type:"doughnut",data:{labels:'.json_encode($planLabels).',datasets:[{data:'.json_encode($planData).',backgroundColor:["#b7ff4a","#8f7cff","#54d9ff","#ff9b54","#ff5f6d"],borderWidth:0}]},options:{maintainAspectRatio:false,cutout:"68%",plugins:{legend:{position:"bottom",labels:{color:tick,padding:18}}}}});new Chart(trafficChart,{type:"line",data:{labels:'.json_encode($hours).',datasets:[{data:'.json_encode($trafficData).',borderColor:"#54d9ff",backgroundColor:"rgba(84,217,255,.08)",fill:true,tension:.35}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{color:tick},grid:{display:false}},y:{ticks:{color:tick,precision:0},grid:{color:grid}}}}});new Chart(joinChart,{type:"bar",data:{labels:'.json_encode($labels).',datasets:[{data:'.json_encode($joins).',backgroundColor:"rgba(143,124,255,.78)",borderRadius:8}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{color:tick},grid:{display:false}},y:{ticks:{color:tick,precision:0},grid:{color:grid}}}}});</script>';include __DIR__.'/../includes/footer.php'; ?>